action.command:
cat > /tmp/verify/verify5.js <<'EOF'
const { chromium } = require('playwright');
(async () => {
    const browser = await chromium.launch();
    const page = await browser.newPage();
    const logs = [];
    page.on('console', m => logs.push(m.type() + ': ' + m.text().slice(0,250)));
    page.on('pageerror', err => logs.push('pageerror: ' + err.message));
    await page.goto('http://localhost/examples/spotify/indexSpotify.html', { waitUntil: 'networkidle' });
    await page.waitForTimeout(2500);
    await page.click('.oneCollapsibleItem.filter .collapsible-header');
    await page.waitForTimeout(500);
    await page.selectOption('#dataExplorerDataFields', 'artists.name');
    await page.waitForTimeout(1500);
    await page.fill('.freeSearchField', 'Weeknd');
    await page.waitForTimeout(500);
    await page.click('.oneCollapsibleItem.output .collapsible-header');
    await page.waitForTimeout(500);
    const select = await page.$('#outputControls select');
    await select.selectOption('simpleTable');
    await page.waitForTimeout(500);
    console.log('BUTTON_STATE: ' + await page.$eval('#getResults', b => JSON.stringify({disabled: b.disabled, classList: b.className})));
    await page.click('#getResults');
    await page.waitForTimeout(6000);
    const recent = logs.filter(l => l.includes('Will') || l.includes('search') || l.includes('Error') || l.includes('error') || l.includes('reject')).slice(-15);
    console.log('POST_CLICK_LOGS: ' + JSON.stringify(recent, null, 1));
    console.log('GRAPHICS: ' + (await page.$eval('#graphicsWrapper', el => el.innerHTML.slice(0,300)).catch(()=>'n/a')));
    await browser.close();
})().catch(e => { console.error('VERIFY_FAILED', e.message); process.exit(1); });
EOF
cd /tmp/verify && node verify5.js 2>&1 | tail -30

